		{ type = "interact" },
	},
	hint = [=[Seek out the general of the Sentinels in her island stronghold off the western coast.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Shandris Feathermoon is the General of the Sentinel Army, the sword of {link:tyrande-whisperwind}Tyrande Whisperwind{/link} and the first soldier of the {link:night-elves}night elves{/link}. She does not command from {link:darnassus}Darnassus{/link}. She has made her seat in {link:feathermoon-stronghold}Feathermoon Stronghold{/link}, on an island off the coast of {link:feralas}Feralas{/link}, at the southern edge of the lands her people still guard. Her voice is brisk, her words are few, and those who serve her well are thanked, paid and sent out again.]=],
		},
		{
			title = "Significance",
			text = [=[The {link:sentinels}Sentinels{/link} are the army of a people who were never meant to need one in this age. Since the {link:third-war}Third War{/link}, they have fought the {link:horde}Horde{/link} in {link:ashenvale}Ashenvale{/link} and the {link:stonetalon-mountains}Stonetalon Mountains{/link}, and Shandris holds that line across all of {link:kalimdor}Kalimdor{/link}. {link:feralas}Feralas{/link} is her answer to a larger question: what will be left of the wild world when the war ends? She came south to keep the last green lands of the continent out of the Horde's hands, and she means to keep them.

Her tales reach back further than any war of the present. It is told that she was a child when the {link:war-of-the-ancients}War of the Ancients{/link} broke her world, an orphan whom the young priestess {link:tyrande-whisperwind}Tyrande{/link} took into her care.]=],
		},
		{
			title = "Deeds",
			text = [=[• She led the expedition of the {link:sentinels}Sentinels{/link} into {link:feralas}Feralas{/link} and built {link:feathermoon-stronghold}Feathermoon Stronghold{/link}.
• She sent scouts into the {link:ruins-of-solarsal}Ruins of Solarsal{/link} when the Hatecrest {link:naga}naga{/link} gathered there, and gave the naga campaign to her second, {link:latronicus-moonspear}Latronicus Moonspear{/link}.
• She has refused to throw her whole force against the naga, for fear of leaving the stronghold open to the {link:horde}Horde{/link}, or to something worse.
• She sent word of the Zukk'ash hive to {link:darnassus}Darnassus{/link}, and a copy of the courier {link:raschal-the-courier}Raschal{/link}'s report to the priestess Gracina Spiritmight of the {link:temple-of-the-moon}Temple of the Moon{/link}.
• The druid {link:quintis-jonespyre}Quintis Jonespyre{/link} names her, with the Protectorate, among the colleagues who question the Arch Druid's hunger for morrowgrain.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle yet written says when Shandris was made general, or what she did in the {link:third-war}Third War{/link} itself. The tales of her childhood come from the histories of the {link:war-of-the-ancients}War of the Ancients{/link}, not from her own mouth.]=],
		},
	},
	chapters = {
		{
			key = "the-warm-stone",
			title = "The Warm Stone",
			hint = "Search the old ruins at the south of the general's island.",
			unlock = {
				{ type = "quest", id = 2867 },
			},
			text = [=[Shandris had thought the {link:ruins-of-solarsal}Ruins of Solarsal{/link} empty. When the {link:naga}naga{/link} came to them in numbers, she first took it for the start of an attack, but she was not sure. The report that came back described a gazebo newer than the ruins, glyphs no one could read, and stone that was warm under the hand. She called it disturbing. Whatever the naga meant to do, she now knew they meant to stay.]=],
		},
		{
			key = "against-the-hatecrest",
			title = "Against the Hatecrest",
			hint = "Answer the general's call against the naga.",
			unlock = {
				{ type = "quest", id = 3130 },
			},
			text = [=[Shandris weighed the matter as a general must. She wanted to strike the {link:naga}naga{/link} with every blade she had. She also knew what an empty stronghold would invite. In the end she gave the task to {link:latronicus-moonspear}Latronicus{/link}, who had watched the naga longest, and kept her own eyes on the wider war.]=],
		},
		{
			key = "rise-of-the-silithid",
			title = "Rise of the Silithid",
			hint = "Receive the general's thanks for the courier's rescue.",
			unlock = {
				{ type = "quest", id = 4267 },
			},
			text = [=[When {link:raschal-the-courier}Raschal{/link} came home alive from the {link:the-writhing-deep}Writhing Deep{/link}, Shandris thanked his rescuers herself. Then she turned at once to his report. Insects that seal living elves inside pods were not a matter for one stronghold. She sent the report to {link:darnassus}Darnassus{/link} and a copy to a priestess who knew such creatures, and bade Elune watch over them all.]=],
		},
	},
	mentions = {
		{
			text = "The {link:ruins-of-solarsal}Ruins of Solarsal{/link}",
			unlock = {
				{ type = "quest", id = 2866 },
			},
