	sections = {
		{
			title = "Summary",
			text = [=[Ginro Hearthkindle is a soldier of {link:feathermoon-stronghold}Feathermoon Stronghold{/link} who would not give up on a friend. When the courier {link:raschal-the-courier}Raschal{/link} vanished on the road to {link:thalanaar}Thalanaar{/link}, Ginro went out into the wilds every day to find him, and came back every night with nothing but {link:gnolls}gnoll{/link} teeth. Even after the stronghold declared Raschal lost, he kept looking.]=],
