			hint = "Drive back the gnolls that raid Camp Mojache.",
			unlock = {
				{ type = "quest", id = 2863 },
			},
			text = [=[The Woodpaw had always raided the camp, and the {link:horde}Horde{/link} had always held them off. Lately the raids had grown savage and constant, as though the gnolls had nowhere else to go. Hadoken meant to break them with one sharp blow. It worked, for a time. It also made him wonder what had driven them to such a frenzy.]=],
