Add({
	kind = "figure",
	id = "witch-doctor-uzer-i",
	title = "Witch Doctor Uzer'i",
	aliases = { "Uzer'i" },
	subtitle = "Witch Doctor of Camp Mojache",
	tier = "B",
	region = "feralas",
	npc = { 8115 },
	allegiance = "Horde · Camp Mojache",
	found = "Camp Mojache",
	pin = { x = 74.4, y = 43.4 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Speak with the troll witch doctor of Camp Mojache who seeks a special vessel.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Witch Doctor Uzer'i is a troll of {link:camp-mojache}Camp Mojache{/link} and a master of an old and unsettling art. He knows the muisek, the spirit that a creature leaves behind when it dies by violence. Such a spirit, he teaches, may escape, seek revenge, and even return in the shape of a greater beast. Uzer'i has found a way to stop it. A creature shrunk and captured in the moment of its death cannot let its muisek go, and a captured muisek can be used.]=],
		},
		{
			title = "Significance",
			text = [=[Uzer'i's work is a weapon aimed at the night elves. He chooses his creatures for their bond with the {link:night-elves}kaldorei{/link}: the wildkin, once the pets of Elune; the hippogryphs, their loyal mounts; the faerie dragons, their allies; the treants, their protectors; and the mountain giants, who came down from their peaks to aid them against the {link:burning-legion}Burning Legion{/link}. Their strength, he says, should serve the {link:horde}Horde{/link} as well.]=],
		},
		{
			title = "Deeds",
