			hint = "Carry a dead dwarf's journal to Thalanaar.",
			unlock = {
				{ type = "quest", id = 1101 },
			},
			text = [=[The journal of Henrig Lonebrow told Falfindel of the druid {link:heralath-fallowbrook}Heralath{/link}, captured in {link:razorfen-kraul}the Kraul{/link}, and of a crone who grew stronger by the day. There was no time to ask {link:darnassus}Darnassus{/link} for help. When the crone's medallion came back to him, he dared to hope that his studies could go on, though he feared the answer to them would be treachery.]=],
		},
