			hint = "Carry Keeper Albagorm's plea to the druid of Thalanaar.",
			unlock = {
				{ type = "quest", id = 1059 },
			},
			text = [=[The harpies of the {link:the-charred-vale}Charred Vale{/link} had been broken, but they would return, and seeds alone could not heal the vale before they did. {link:keeper-albagorm}Albagorm{/link} sent word across half of {link:kalimdor}Kalimdor{/link} to Falfindel. The druid did not waste words. He turned at once to calling help from the great forest.]=],
